-- Dontalist on TiDB Cloud (MySQL dialect). Rules this file follows:
--  * no triggers, procedures or events (TiDB has none); immutability and audit are enforced by the Worker services
--  * CHECK is not relied on (TiDB ships it switched off); validation lives in the Worker
--  * every clinic-owned table has clinic_id and a UNIQUE (clinic_id, id) so child tables can use composite foreign keys
--  * ids are CHAR(26), generated by the Worker (time-ordered prefix + random); instants are UTC DATETIME(3)
--  * the Worker never accepts clinic_id from a client: it comes from the verified session

CREATE TABLE clinic (
  id CHAR(26) NOT NULL,
  name VARCHAR(160) NOT NULL,
  country CHAR(2) NOT NULL,
  timezone VARCHAR(64) NOT NULL,
  status ENUM('active','suspended') NOT NULL DEFAULT 'active',
  created_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE staff (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  email_norm VARCHAR(254) NOT NULL,
  name VARCHAR(120) NOT NULL,
  role ENUM('owner','admin','dentist','assistant','reception','accountant') NOT NULL,
  job_title VARCHAR(80) NULL,
  password_hash VARCHAR(255) NOT NULL,
  status ENUM('active','suspended','deactivated') NOT NULL DEFAULT 'active',
  status_reason VARCHAR(255) NULL,
  failed_logins SMALLINT NOT NULL DEFAULT 0,
  locked_until DATETIME(3) NULL,
  password_changed_at DATETIME(3) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_staff_clinic_id (clinic_id, id),
  UNIQUE KEY uq_staff_email (email_norm),
  CONSTRAINT fk_staff_clinic FOREIGN KEY (clinic_id) REFERENCES clinic (id)
) DEFAULT CHARSET=utf8mb4;

-- The owner's changes to a role's defaults (auth-rules.ts: extra / removed).
CREATE TABLE staff_permission (
  clinic_id CHAR(26) NOT NULL,
  staff_id CHAR(26) NOT NULL,
  permission VARCHAR(40) NOT NULL,
  effect ENUM('extra','removed') NOT NULL,
  PRIMARY KEY (clinic_id, staff_id, permission),
  CONSTRAINT fk_perm_staff FOREIGN KEY (clinic_id, staff_id) REFERENCES staff (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- Opaque server-side sessions. Only the SHA-256 of the cookie token is stored.
CREATE TABLE auth_session (
  token_hash CHAR(64) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  staff_id CHAR(26) NOT NULL,
  csrf_token CHAR(43) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  last_seen_at DATETIME(3) NOT NULL,
  idle_expires_at DATETIME(3) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  revoked_at DATETIME(3) NULL,
  revoked_reason VARCHAR(40) NULL,
  user_agent VARCHAR(200) NULL,
  PRIMARY KEY (token_hash),
  KEY ix_session_staff (clinic_id, staff_id, revoked_at),
  CONSTRAINT fk_session_staff FOREIGN KEY (clinic_id, staff_id) REFERENCES staff (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- One-time reset links issued by an owner/admin (self-service e-mail recovery needs a mail provider: undecided).
CREATE TABLE password_reset (
  token_hash CHAR(64) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  staff_id CHAR(26) NOT NULL,
  issued_by CHAR(26) NOT NULL,
  expires_at DATETIME(3) NOT NULL,
  used_at DATETIME(3) NULL,
  PRIMARY KEY (token_hash),
  CONSTRAINT fk_reset_staff FOREIGN KEY (clinic_id, staff_id) REFERENCES staff (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- Append-only by construction: the repository exposes insert and read only.
CREATE TABLE audit_event (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  at DATETIME(3) NOT NULL,
  actor_staff_id CHAR(26) NULL,
  action VARCHAR(48) NOT NULL,
  entity_type VARCHAR(32) NOT NULL,
  entity_id CHAR(26) NULL,
  detail VARCHAR(1000) NULL,
  PRIMARY KEY (id),
  KEY ix_audit_clinic_at (clinic_id, at),
  KEY ix_audit_entity (clinic_id, entity_type, entity_id)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE patient (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  full_name VARCHAR(160) NOT NULL,
  phone VARCHAR(40) NOT NULL,
  email VARCHAR(254) NULL,
  birth_date DATE NULL,
  sex ENUM('female','male') NULL,
  country CHAR(2) NULL,
  city VARCHAR(80) NULL,
  alert VARCHAR(500) NULL,
  notes TEXT NULL,
  archived_at DATETIME(3) NULL,
  version INT NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL,
  updated_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_patient_clinic_id (clinic_id, id),
  KEY ix_patient_name (clinic_id, full_name),
  KEY ix_patient_phone (clinic_id, phone),
  CONSTRAINT fk_patient_clinic FOREIGN KEY (clinic_id) REFERENCES clinic (id)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE chair (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  name VARCHAR(60) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_chair_clinic_id (clinic_id, id),
  CONSTRAINT fk_chair_clinic FOREIGN KEY (clinic_id) REFERENCES clinic (id)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE appointment (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  patient_id CHAR(26) NOT NULL,
  dentist_id CHAR(26) NOT NULL,
  chair_id CHAR(26) NOT NULL,
  type VARCHAR(32) NOT NULL,
  status ENUM('scheduled','confirmed','arrived','in-progress','completed','cancelled','no-show') NOT NULL DEFAULT 'scheduled',
  start_at DATETIME(3) NOT NULL,
  end_at DATETIME(3) NOT NULL,
  reason VARCHAR(200) NULL,
  note VARCHAR(1000) NULL,
  created_by CHAR(26) NOT NULL,
  version INT NOT NULL DEFAULT 1,
  created_at DATETIME(3) NOT NULL,
  updated_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_appt_clinic_id (clinic_id, id),
  KEY ix_appt_day (clinic_id, start_at),
  KEY ix_appt_patient (clinic_id, patient_id, start_at),
  KEY ix_appt_dentist (clinic_id, dentist_id, start_at),
  CONSTRAINT fk_appt_patient FOREIGN KEY (clinic_id, patient_id) REFERENCES patient (clinic_id, id),
  CONSTRAINT fk_appt_dentist FOREIGN KEY (clinic_id, dentist_id) REFERENCES staff (clinic_id, id),
  CONSTRAINT fk_appt_chair FOREIGN KEY (clinic_id, chair_id) REFERENCES chair (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

CREATE TABLE appointment_status_change (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  appointment_id CHAR(26) NOT NULL,
  at DATETIME(3) NOT NULL,
  by_staff_id CHAR(26) NOT NULL,
  from_status VARCHAR(16) NULL,
  to_status VARCHAR(16) NOT NULL,
  note VARCHAR(255) NULL,
  PRIMARY KEY (id),
  KEY ix_apptchg (clinic_id, appointment_id, at),
  CONSTRAINT fk_apptchg_appt FOREIGN KEY (clinic_id, appointment_id) REFERENCES appointment (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- Examination header. Signed rows are never updated; a correction is a NEW row with supersedes_id set.
-- chart_json is INTERIM: the relational odontogram tables wait on decision D9 (see docs/architecture-tidb.md).
CREATE TABLE examination (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  patient_id CHAR(26) NOT NULL,
  examiner_id CHAR(26) NOT NULL,
  status ENUM('draft','signed','void') NOT NULL DEFAULT 'draft',
  supersedes_id CHAR(26) NULL,
  chart_json JSON NOT NULL,
  note VARCHAR(2000) NULL,
  signed_at DATETIME(3) NULL,
  voided_at DATETIME(3) NULL,
  voided_by CHAR(26) NULL,
  void_reason VARCHAR(500) NULL,
  created_at DATETIME(3) NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_exam_clinic_id (clinic_id, id),
  KEY ix_exam_patient (clinic_id, patient_id, created_at),
  CONSTRAINT fk_exam_patient FOREIGN KEY (clinic_id, patient_id) REFERENCES patient (clinic_id, id),
  CONSTRAINT fk_exam_examiner FOREIGN KEY (clinic_id, examiner_id) REFERENCES staff (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- File bytes live in R2; this row is the only way to reach them.
CREATE TABLE file_object (
  id CHAR(26) NOT NULL,
  clinic_id CHAR(26) NOT NULL,
  patient_id CHAR(26) NULL,
  kind ENUM('document','xray','photo','pdf','other') NOT NULL,
  r2_key VARCHAR(80) NOT NULL,
  filename VARCHAR(200) NOT NULL,
  mime VARCHAR(80) NOT NULL,
  size_bytes INT NOT NULL,
  sha256 CHAR(64) NOT NULL,
  uploaded_by CHAR(26) NOT NULL,
  created_at DATETIME(3) NOT NULL,
  deleted_at DATETIME(3) NULL,
  deleted_by CHAR(26) NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_file_clinic_id (clinic_id, id),
  UNIQUE KEY uq_file_key (r2_key),
  KEY ix_file_patient (clinic_id, patient_id, created_at),
  CONSTRAINT fk_file_patient FOREIGN KEY (clinic_id, patient_id) REFERENCES patient (clinic_id, id)
) DEFAULT CHARSET=utf8mb4;

-- Public clinic page record (the shape parseRecords() reads). JSON because it is a flexible, display-only document.
CREATE TABLE clinic_public_profile (
  clinic_id CHAR(26) NOT NULL,
  payload JSON NOT NULL,
  published_at DATETIME(3) NOT NULL,
  PRIMARY KEY (clinic_id),
  CONSTRAINT fk_public_clinic FOREIGN KEY (clinic_id) REFERENCES clinic (id)
) DEFAULT CHARSET=utf8mb4;
